# Apply the verified pattern: 2 becomes 4 if (n5_ortho + n5_diag) >= 3
# where n5 is count of neighbors equal to the other dominant color

test_grid = [
    [7, 7, 2, 7, 2, 2, 2, 2],
    [2, 2, 2, 2, 7, 2, 7, 2],
    [7, 7, 2, 2, 7, 2, 2, 2],
    [7, 7, 7, 7, 7, 7, 7, 2],
    [7, 2, 7, 2, 7, 7, 7, 7],
    [7, 2, 7, 2, 2, 7, 2, 2],
    [7, 2, 7, 7, 2, 7, 7, 7],
    [2, 7, 2, 2, 2, 2, 2, 7],
    [2, 2, 7, 2, 2, 2, 2, 7],
    [7, 2, 2, 2, 7, 2, 2, 7]
]

def apply_rule(grid, dominant):
    """Apply the rule: 2 becomes 4 if (n_ortho + n_diag of dominant) >= 3"""
    rows, cols = len(grid), len(grid[0])
    output = [row[:] for row in grid]

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 2:
                n_dominant_ortho = 0
                n_dominant_diag = 0

                # Orthogonal neighbors
                for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == dominant:
                        n_dominant_ortho += 1

                # Diagonal neighbors  
                for dr, dc in [(-1, -1), (-1, 1), (1, -1), (1, 1)]:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == dominant:
                        n_dominant_diag += 1

                if n_dominant_ortho + n_dominant_diag >= 3:
                    output[r][c] = 4

    return output

# Debug: print each 2's neighbor counts
print("Debugging neighbor counts:")
for r in range(len(test_grid)):
    for c in range(len(test_grid[0])):
        if test_grid[r][c] == 2:
            n_orth = 0
            n_diag = 0
            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < len(test_grid) and 0 <= nc < len(test_grid[0]):
                    if test_grid[nr][nc] == 7:
                        n_orth += 1
            for dr, dc in [(-1, -1), (-1, 1), (1, -1), (1, 1)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < len(test_grid) and 0 <= nc < len(test_grid[0]):
                    if test_grid[nr][nc] == 7:
                        n_diag += 1
            total = n_orth + n_diag
            status = "becomes 4" if total >= 3 else "stays 2"
            print(f"({r},{c}): orth={n_orth}, diag={n_diag}, total={total} -> {status}")

result = apply_rule(test_grid, 7)
print("\nResult:")
for row in result:
    print(row)

