def get_connected_component(grid, start_pos):
    """Find connected component of same-color cells"""
    from collections import deque
    rows, cols = len(grid), len(grid[0])
    q = deque([start_pos])
    visited = {start_pos}
    component = []

    while q:
        r, c = q.popleft()
        component.append((r,c))

        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr, nc = r+dr, c+dc
            if 0 <= nr < rows and 0 <= nc < cols and (nr,nc) not in visited:
                if grid[nr][nc] == grid[r][c]:
                    visited.add((nr,nc))
                    q.append((nr,nc))
    return component

