# A "streak" means consecutive same-color cells in a row/column

def get_row_streak_length(grid, r, c):
    """Get length of streak going horizontally"""
    val = grid[r][c]

    left = 0
    for dc in range(-1, -len(grid[0])-1, -1):
        cc = c + dc
        if cc < 0:
            break
        if grid[r][cc] == val:
            left += 1
        else:
            break

    right = 0
    for dc in range(1, len(grid[0])):
        cc = c + dc
        if cc >= len(grid[0]):
            break
        if grid[r][cc] == val:
            right += 1
        else:
            break

    return max(left, right)

def get_col_streak_length(grid, r, c):
    """Get length of streak going vertically"""
    val = grid[r][c]

    up = 0
    for dr in range(-1, -len(grid), -1):
        rr = r + dr
        if rr < 0:
            break
        if grid[rr][c] == val:
            up += 1
        else:
            break

    down = 0
    for dr in range(1, len(grid)):
        rr = r + dr
        if rr >= len(grid):
            break
        if grid[rr][c] == val:
            down += 1
        else:
            break

    return max(up, down)

